210|  let best: EmotionId = EMOTIONS[0] as EmotionId;
211|  let bestValue = -Infinity;
212|  EMOTIONS.forEach((id: EmotionId, i: number) => {
213|    const value = norm[i] ?? 0;
214|    if (value > bestValue) {
215|      bestValue = value;
216|      best = id;
217|    }
218|  });
219|  return best;
