111|  const values = EMOTIONS.map((id: EmotionId) => {
112|    const v = vector[id];
113|    return typeof v === "number" && Number.isFinite(v) ? v : 0;
114|  });
115|  const sum = values.reduce((a, b) => a + b, 0);
116|  if (sum <= 0) return values.map(() => 0);
117|  return values.map((v) => v / sum);
