120|// Bhattacharyya affinity over the renormalized shapes, plus separate
121|// intensity and tempo terms. Fair to blended scenes, unlike cosine.
122|export function bhattacharyyaSimilarity(
123|  scene: SceneSignal,
124|  track: Track,
125|  weights: MusicWeights = MUSIC_CONFIG.weights,
126|): number {
127|  const s = normalize8(scene.vector);
128|  const t = normalize8(track.vector);
129|  let affinity = 0;
130|  for (let i = 0; i < s.length; i++) {
131|    affinity += Math.sqrt((s[i] ?? 0) * (t[i] ?? 0));
132|  }
133|  return (
134|    weights.emotion * affinity +
135|    weights.intensity * (1 - Math.abs(scene.intensity - track.intensity)) +
136|    weights.tempo * (1 - Math.abs(scene.tempo - track.tempo))
137|  );
