147|  let nb = 0;
148|  for (let i = 0; i < a.length; i++) {
149|    const x = a[i] ?? 0;
150|    const y = b[i] ?? 0;
151|    dot += x * y;
152|    na += x * x;
153|    nb += y * y;
154|  }
