19|export interface Track {
20|  id: string;
21|  src: string;
22|  title: string;
23|  playlistOnly?: boolean;
24|  emotion: EmotionId;
25|  vector: Vector8;
26|  intensity: number;
27|  tempo: number;
28|  durationSec: number;
29|  startSec: number;
30|  loop: boolean;
31|  soundtrack: string;
32|  style: string;
33|  source?: TrackSource;
34|  artist?: string;
35|  composer?: string;
36|  license?: string;
